type FollowUpCategory = "metric" | "team" | "project" | "action"

/** Used when a follow-up's wording changes slightly and no exact entry matches. */
const FOLLOW_UP_BY_CATEGORY: Record<"en" | "ms", Record<FollowUpCategory, string>> = {
  en: { metric: FU_EN.metricNormal, team: FU_EN.teamNormal, project: FU_EN.project, action: FU_EN.action },
  ms: { metric: FU_MS.metricNormal, team: FU_MS.teamNormal, project: FU_MS.projectNormal, action: FU_MS.action },
}

/** Opening words that mark a probing follow-up rather than a fresh question. */
const FOLLOW_UP_CUE_EN =
  /^(you mentioned|you touched|you keep|you said|that answer|could you (walk|dive|elaborate|tell|explain)|can you (walk|elaborate|tell|explain))/i
const FOLLOW_UP_CUE_MS =
  /^(anda (banyak )?menyebut|anda kata|dalam projek itu|jawapan anda|boleh (anda )?(huraikan|terangkan|jelaskan))/i

function followUpCategory(text: string, isMalay: boolean): FollowUpCategory {
  const t = text.toLowerCase()
  if (isMalay) {
    if (/(metrik|angka|hasil|diukur|peratus)/.test(t)) return "metric"
    if (/(pasukan|kerjasama|rakan|pihak berkepentingan)/.test(t)) return "team"
    if (/projek/.test(t)) return "project"
    return "action"
  }
  if (/(metric|number|measurable|result|before and after)/.test(t)) return "metric"
  if (/(team|'we'|buy-in|stakeholder|personally)/.test(t)) return "team"
  if (/project/.test(t)) return "project"
  return "action"
}

/* ======================================================================== */
/* Resume and job-ad template answers                                       */
/* ======================================================================== */

type TemplateKind = "skill" | "role" | "keyword" | "word"
type Fill = (value: string) => string

interface TemplateAnswerSet {
  skill: Record<InterviewType, Fill>
  role: Record<InterviewType, Fill>
  keyword: Record<InterviewType, Fill>
  word: Fill
}

/** Matches the wording of RESUME_SKILL_TEMPLATES, RESUME_ROLE_TEMPLATES, JOB_AD_TEMPLATES and JOB_AD_WORD_TEMPLATES. */
const TEMPLATE_PATTERNS: Record<"en" | "ms", { re: RegExp; kind: TemplateKind }[]> = {
  en: [
    { re: /^Your resume targets (.+?) roles\./i, kind: "role" },
    { re: /^Your resume (?:mentions|highlights) (.+?)\.\s/i, kind: "skill" },
    { re: /^You list (.+?) on your resume\./i, kind: "skill" },
    { re: /^How would you use (.+?) on the first real task you get in this role\?/i, kind: "skill" },
    { re: /^Describe a situation where your experience with (.+?) was put to the test/i, kind: "skill" },
    { re: /^How do you think your experience with (.+?) will help you contribute/i, kind: "skill" },
    { re: /^The job ad (?:mentions|talks about) "(.+?)"\./i, kind: "word" },
    { re: /^This role asks for (.+?)\.\s/i, kind: "keyword" },
    { re: /^The job ad (?:mentions|highlights) (.+?)\.\s/i, kind: "keyword" },
    { re: /^How would you use (.+?) in your first month in this role\?/i, kind: "keyword" },
  ],
  ms: [
    { re: /^Resume anda menyasarkan jawatan (.+?)\.\s/i, kind: "role" },
    { re: /^Resume anda (?:menyebut|menonjolkan) (.+?)\.\s/i, kind: "skill" },
    { re: /^Anda menyenaraikan (.+?) dalam resume anda\./i, kind: "skill" },
    { re: /^Bagaimana anda akan menggunakan (.+?) untuk tugasan sebenar pertama/i, kind: "skill" },
    { re: /pengalaman anda dengan (.+?) (?:benar-benar diuji|boleh membantu)/i, kind: "skill" },
    { re: /^Iklan jawatan ini (?:menyebut|ada menyebut tentang) "(.+?)"\./i, kind: "word" },
    { re: /^Jawatan ini memerlukan (.+?)\.\s/i, kind: "keyword" },
    { re: /^Iklan jawatan ini (?:menyebut|menekankan) (.+?)\.\s/i, kind: "keyword" },
    { re: /^Bagaimana anda akan menggunakan (.+?) dalam bulan pertama/i, kind: "keyword" },
  ],
}

