/* ======================================================================== */
/* Lookup                                                                   */
/* ======================================================================== */

const normalise = (text: string): string => text.trim().toLowerCase().replace(/\s+/g, " ")

function buildLookup(maps: AnswerMap[]): Map<string, string> {
  const lookup = new Map<string, string>()
  for (const map of maps) {
    for (const [question, answer] of Object.entries(map)) lookup.set(normalise(question), answer)
  }
  return lookup
}

const EXACT_ANSWERS = buildLookup([ANSWERS_EN, ANSWERS_MS, FOLLOW_UPS_EN, FOLLOW_UPS_MS])

const INTERVIEW_TYPES: readonly InterviewType[] = ["hr", "behavioral", "technical"]

/** Cleans a value pulled from a template question: trims spaces, quotes and trailing punctuation. */
function cleanValue(value: string): string {
  return value.replace(/^["'\s]+|["'\s.,;:!?]+$/g, "").replace(/\s+/g, " ")
}

/** "the Data Analyst role" / "jawatan Data Analyst", or "this role" / "jawatan ini" for General or empty. */
function rolePhrase(role: string, isMalay: boolean): string {
  const r = (role ?? "").trim().replace(/\s+/g, " ")
  const isGeneral = !r || r.toLowerCase() === "general"
  if (isMalay) return isGeneral ? "jawatan ini" : `jawatan ${r}`
  return isGeneral ? "this role" : `the ${r} role`
}

function templateAnswer(text: string, type: InterviewType, preferMalay: boolean): string | null {
  const order: ("en" | "ms")[] = preferMalay ? ["ms", "en"] : ["en", "ms"]
  for (const lang of order) {
    for (const { re, kind } of TEMPLATE_PATTERNS[lang]) {
      const match = re.exec(text)
      if (!match) continue
      const value = cleanValue(match[1] ?? "")
      if (!value) return null
      const set = lang === "ms" ? TEMPLATE_ANSWERS_MS : TEMPLATE_ANSWERS_EN
      return kind === "word" ? set.word(value) : set[kind][type](value)
    }
  }
  return null
}

/** Suggested spoken answer for a question, in the question's language. Never returns an empty string. */
export function getSuggestedAnswer(input: {
  text: string
  type: InterviewType
  role: string
  language: Language
}): string {
  const text = (input.text ?? "").trim()
  const type: InterviewType = INTERVIEW_TYPES.includes(input.type) ? input.type : "behavioral"

  // 1 and 2. Bank question or exact follow-up wording.
  const exact = EXACT_ANSWERS.get(normalise(text))
  if (exact) return exact

  const isMalay = input.language === "ms-MY" || /\banda\b/i.test(text)

  // 3. Resume / job-ad template question.
  const fromTemplate = templateAnswer(text, type, isMalay)
  if (fromTemplate) return fromTemplate

  // 4. Follow-up whose wording differs slightly from generateProbingFollowUp.
  if ((isMalay ? FOLLOW_UP_CUE_MS : FOLLOW_UP_CUE_EN).test(text)) {
    return FOLLOW_UP_BY_CATEGORY[isMalay ? "ms" : "en"][followUpCategory(text, isMalay)]
  }

  // 5. Generic STAR answer for the interview type, mentioning the role.
  return (isMalay ? GENERIC_MS : GENERIC_EN)[type](rolePhrase(input.role, isMalay))
}
